1	import { finding } from '../../engine/checks/helpers/findings.mjs';
2	
3	const rule = {
4	  id: 'task-lifecycle',
5	  severity: 'blocking',
6	  description: 'Work on a branch must reference a GitHub issue in at least one commit message',
7	  doc: 'packs/basics/RULES.md',
8	  scope: 'work',
9	  why: 'every task starts from an issue; the reference is what ties the branch to it',
10	
11	  run(work) {
12	    const { commits } = work;
13	    if (work.onDefaultBranch() || !commits.length || commits.some((m) => /#\d+/.test(m))) return [];
14	    return [finding(rule, {
15	      file: '(branch)',
16	      what: `none of the ${commits.length} commit(s) since ${work.baseRef} references an issue (#N)`,
17	      fix: 'create or locate the GitHub issue for this task and reference it (e.g. "Refs #N", "Closes #N") in a commit message — amending the latest commit is fine',
18	    })];
19	  },
20	};
21	
22	export default rule;
23

